<script>
  import { onMount, onDestroy, tick, untrack } from 'svelte'
  import { ArrowLeft, ArrowUpRight, Check, CircleAlert, Info, Pause, ChevronDown, Bot, ListOrdered, FileText, RefreshCw } from 'lucide-svelte'
  import { getJournal, getSeatSessions } from './api.js'
  import { leanView, leanOutcome, leanStageStatus, leanCheckStatus, leanPullRequestUrl, leanLabel } from './lean.js'
  import { journalPulse } from './live.js'
  import LeanWaterfall from './LeanWaterfall.svelte'
  import DeveloperTools from './DeveloperTools.svelte'
  let { run, onback = () => {} } = $props()
  let journal=$state(null),journalError=$state(''),journalLoading=$state(false),role=$state(''),sessionLoading=$state(false)
  let loadedTaskIdentity=null,loadedSeatIdentity=null
  let sessions=$state({sessions:[],absent:null,error:''}),heading=$state(),journalGeneration=0,sessionGeneration=0
  let view=$derived(leanView(run,journal)),outcome=$derived(leanOutcome(run)),activeRole=$derived(view.seats.some(seat=>seat.role===role)?role:view.seats.find(seat=>seat.role===run.phases?.find(phase=>phase.role)?.role)?.role || view.seats[0]?.role || '')
  let phases=$derived(Array.isArray(run.phases)?run.phases:[]),prUrl=$derived(leanPullRequestUrl(view.pr))
  let activeSeat=$derived(view.seats.find(seat=>seat.role===activeRole)),skipped=$derived(journal?.skipped_malformed ?? run.journal_skipped_malformed ?? 0)
  const icons={check:Check,pause:Pause,alert:CircleAlert,info:Info}
  const stageIcons={ok:Check,fail:CircleAlert,attention:Pause,quiet:Info}
  let OutcomeIcon=$derived(icons[outcome.icon])
  async function loadJournal(){
    const token=++journalGeneration,identity=run.adw_id;journalLoading=true
    try{const result=await getJournal(run.repo_slug,run.goal,identity);if(token!==journalGeneration || identity!==run.adw_id)return;journal=result;journalError=result?.error || ''}
    catch(error){if(token===journalGeneration && identity===run.adw_id)journalError=error.message || 'Journal request failed.'}
    finally{if(token===journalGeneration)journalLoading=false}
  }
  async function loadSessions(name,{reset=false}={}){
    const token=++sessionGeneration,identity=run.adw_id
    if(reset)sessions={sessions:[],absent:null,error:''}
    if(!name){sessionLoading=false;return}sessionLoading=true
    try{const result=await getSeatSessions(run.repo_slug,run.goal,identity,name);if(token===sessionGeneration && identity===run.adw_id && name===activeRole)sessions={sessions:result.sessions ?? [],absent:result.absent ?? null,error:result.errors?.map(item=>`${item.file}: ${item.error}`).join('; ') || ''}}
    catch(error){if(token===sessionGeneration && identity===run.adw_id && name===activeRole)sessions={...sessions,error:error.message || 'Session request failed.'}}
    finally{if(token===sessionGeneration)sessionLoading=false}
  }
  $effect(()=>{const identity=run.adw_id;if(identity===loadedTaskIdentity)return;loadedTaskIdentity=identity;untrack(()=>{role='';journal=null;journalError='';void loadJournal();void tick().then(()=>heading?.focus())})})
  $effect(()=>{const selected=activeRole,identity=`${run.adw_id}:${selected}`;if(identity===loadedSeatIdentity)return;loadedSeatIdentity=identity;untrack(()=>{void loadSessions(selected,{reset:true})})})
  onMount(()=>journalPulse.subscribe(()=>{void loadJournal();void loadSessions(activeRole)}))
  onDestroy(()=>{journalGeneration++;sessionGeneration++})
  const started=value=>{const date=new Date(value);return value && Number.isFinite(date.getTime())?date.toLocaleString():null}
</script>
<main class="lean-detail">
  <header class="task-header"><button class="back" onclick={onback}><ArrowLeft size={16} aria-hidden="true" />Back to tasks</button><p class="eyebrow">Lean task · recorded evidence</p><h1 tabindex="-1" bind:this={heading}>{view.lane || 'Task name not recorded'}</h1><p class="subtitle">{started(run.started_at)?`Started ${started(run.started_at)} · local time`:'Start time not recorded'}{run.archived?' · Archived':''}</p></header>
  <section class={`outcome-card ${outcome.tone}`} aria-label="Task outcome"><span class="outcome-icon"><OutcomeIcon size={22} aria-hidden="true" /></span><div><span class="eyebrow">Result and next action</span><h2>{outcome.headline}</h2><p>{outcome.next}</p>{#if view.status.why}<p class="reason"><strong>Recorded reason</strong> {view.status.why}</p>{/if}</div>{#if prUrl}<a class="primary-link" href={prUrl} target="_blank" rel="noreferrer">Open PR #{view.pr?.number || 'recorded'}<ArrowUpRight size={16} aria-hidden="true" /></a>{/if}</section>
  <dl class="facts"><div><dt>Latest recorded stage</dt><dd>{leanLabel(view.stage)}</dd></div><div><dt>Workflow</dt><dd>{leanLabel(run.shape)}</dd></div><div><dt>Assurance</dt><dd>{({mechanical:'Quick',build:'Standard',judge:'Rigorous'})[run.tier] || leanLabel(run.tier)}</dd></div></dl>
  {#if view.pr && !prUrl}<p class="delivery-note">Pull request #{view.pr.number || 'not recorded'} was recorded, but no usable link is available.</p>{/if}
  <section class="card" aria-labelledby="lean-seats-heading"><header class="section-header"><div><p class="eyebrow"><Bot size={15} aria-hidden="true" />Recorded activity</p><h2 id="lean-seats-heading">Execution</h2><p>Inspect lane stages, then select a seat and recording for messages and tool calls.</p></div><button disabled={sessionLoading || !activeRole} onclick={()=>loadSessions(activeRole)}><RefreshCw size={15} aria-hidden="true" />Refresh sessions</button></header>
    <div class="stage-summary" aria-labelledby="stage-summary-heading">
      <div class="stage-summary-header"><h3 id="stage-summary-heading">Stages</h3><span class="count">{phases.length} recorded</span></div>
      {#if phases.length}<ol class="stage-strip">{#each phases as phase,index (phase.id ?? index)}{@const state=leanStageStatus(phase.status)}{@const StageIcon=stageIcons[state.tone] || Info}<li class={state.tone} aria-label={`${index+1}. ${leanLabel(phase.name)}: ${state.label}`} title={state.label}><StageIcon size={13} aria-hidden="true" /><span>{leanLabel(phase.name)}</span></li>{/each}</ol>{:else}<p class="empty">No stages were recorded.</p>{/if}
      <details class="stage-details"><summary><ListOrdered size={15} aria-hidden="true" /><span>Stage timing and checks</span><ChevronDown size={15} class="chevron" aria-hidden="true" /></summary><div class="stage-evidence">
  <LeanWaterfall {run} />
  <section class="card sequence" aria-labelledby="lean-sequence-heading"><header class="section-header"><div><p class="eyebrow"><ListOrdered size={15} aria-hidden="true" />Execution sequence</p><h2 id="lean-sequence-heading">What happened</h2><p>Stages in recorded order. Complete boundaries are measured in the waterfall above.</p></div><span class="count">{phases.length} recorded {phases.length===1?'stage':'stages'}</span></header>
    {#if phases.length}<ol class="stages">{#each phases as phase,index (phase.id ?? index)}{@const state=leanStageStatus(phase.status)}<li><span class="step-number">{String(index+1).padStart(2,'0')}</span><div class="stage-copy"><div class="stage-heading"><h3>{leanLabel(phase.name)}</h3><span class={`status-badge ${state.tone}`}>{state.label}</span></div>{#if phase.checks?.length}<ul class="checks">{#each phase.checks as check}{@const result=leanCheckStatus(check)}<li><span>{leanLabel(check.check)}</span><span class={`check-result ${result.tone}`}>{result.label}</span>{#if check.result?.reason}<p>{check.result.reason}</p>{/if}{#if check.result}<details class="check-evidence"><summary>Inspect check evidence<ChevronDown size={14} class="chevron" aria-hidden="true" /></summary><pre>{JSON.stringify(check.result,null,2)}</pre></details>{/if}</li>{/each}</ul>{/if}</div></li>{/each}</ol>{:else}<p class="empty">No stages were recorded. Refresh the journal or inspect agent sessions below.</p>{/if}
  </section>
      </div></details>
    </div>
    {#if view.seats.length}<div class="seat-picker" role="group" aria-label="Seat role">{#each view.seats as seat (seat.role)}<button aria-pressed={activeRole===seat.role} onclick={()=>role=seat.role}>{leanLabel(seat.role)}</button>{/each}</div>
      <dl class="seat-facts"><div><dt>Harness</dt><dd>{activeSeat?.agent || 'Not recorded'}</dd></div><div><dt>Model</dt><dd>{activeSeat?.model || 'Not recorded'}</dd></div><div><dt>Transport</dt><dd>{activeSeat?.transport || 'Not recorded'}</dd></div></dl>
      {#if sessions.error}<div class="read-error" role="alert"><strong>Could not refresh sessions.</strong><p>{sessions.error} Use Refresh sessions to try again.{sessions.sessions.length?' Previously loaded recordings remain below.':''}</p></div>{/if}
      {#if sessionLoading}<p class="read-status" role="status">Reading sessions…</p>{/if}
      {#if sessions.absent}<p class="empty">{sessions.absent}. Use Refresh sessions to check again.</p>{:else if !sessionLoading && !sessions.error && !sessions.sessions.length}<p class="empty">No sessions were recorded for this role. Use Refresh sessions to check again.</p>{/if}
      {#key `${run.adw_id}:${activeRole}`}<DeveloperTools sessions={sessions.sessions} role={activeRole} model={activeSeat?.model} agent={activeSeat?.agent} />{/key}
      {#each sessions.sessions as session (session.file)}<details class="recording"><summary><FileText size={16} aria-hidden="true" /><span>{session.file}</span><span class="disclosure-hint">Read recording</span><ChevronDown size={16} class="chevron" aria-hidden="true" /></summary><pre>{session.raw || 'This recording is empty.'}</pre></details>{/each}
    {:else}<p class="empty">No seat assignments were recorded for this task.</p>{/if}
  </section>
  <section class="card evidence" aria-labelledby="lean-journal-heading"><header class="section-header"><div><p class="eyebrow">Source evidence</p><h2 id="lean-journal-heading">Task journal</h2><p>Recorded events explain the sequence above. Event order does not measure elapsed time.</p></div><button disabled={journalLoading} onclick={loadJournal}><RefreshCw size={15} aria-hidden="true" />Refresh journal</button></header>
    {#if journalError}<div class="read-error" role="alert"><strong>Could not refresh the journal.</strong><p>{journalError} Use Refresh journal to try again.</p></div>{/if}{#if journalLoading}<p class="read-status" role="status">Reading journal…</p>{/if}
    {#if skipped}<p class="data-warning">{skipped} malformed {skipped===1?'row was':'rows were'} omitted. The journal evidence is incomplete.</p>{/if}
    <details class="journal-disclosure"><summary><FileText size={16} aria-hidden="true" /><span>Recorded journal</span><span class="count">{view.lines.length} events</span><ChevronDown size={16} class="chevron" aria-hidden="true" /></summary>{#if view.lines.length}<ol class="journal-lines">{#each view.lines as line (line.index)}<li><span class="event-number">{line.index+1}</span><div><strong>{leanLabel(line.event)}</strong>{#if line.stage!=='—'}<span class="event-stage">{leanLabel(line.stage)}</span>{/if}{#if line.detail}<p>{line.detail}</p>{/if}</div></li>{/each}</ol>{:else}<p class="empty">{journalLoading?'Reading journal…':'No readable events. Use Refresh journal to check the source again.'}</p>{/if}</details>
  </section>
  <details class="coverage"><summary><Info size={16} aria-hidden="true" /><span>Measurement limits</span><ChevronDown size={16} class="chevron" aria-hidden="true" /></summary><p>A task can remain open in this journal after its agents have stopped. Recorded boundaries measure complete stage intervals, but missing boundaries remain unmeasured. These records do not establish liveness, run-wide token usage or cost, or a merged pull request. Individual turn usage is available in the event inspector when recorded.</p>{#if view.pending.length}<dl>{#each view.pending as item (item.field)}<div><dt>{leanLabel(item.field)}</dt><dd>{item.reason}</dd></div>{/each}</dl>{/if}</details>
</main>
<style>
.lean-detail{width:min(1240px,100%);box-sizing:border-box;margin:auto;padding:2rem 2rem 4rem;display:grid;gap:1.25rem;min-width:0}.lean-detail *{box-sizing:border-box}h1,h2,h3,p,dl,dd{margin:0}h1{font-size:clamp(1.6rem,3vw,2.2rem);line-height:1.2;letter-spacing:-.025em;overflow-wrap:anywhere}h2{font-size:1.1rem;line-height:1.3}h3{font-size:1rem;line-height:1.4;font-weight:650;text-transform:capitalize}p{line-height:1.55;max-width:75ch}button,a{font:inherit}button{max-width:100%;white-space:normal;overflow-wrap:anywhere;display:inline-flex;align-items:center;justify-content:center;gap:.5rem;padding:.6rem .85rem;border:1px solid var(--line);border-radius:.5rem;background:var(--panel);color:var(--text);font-size:.85rem;min-height:2.65rem;cursor:pointer}button:disabled{opacity:.55;cursor:default}a{color:var(--accent);text-underline-offset:.2em;display:inline-flex;align-items:center;gap:.3rem;overflow-wrap:anywhere}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.task-header{display:grid;gap:.6rem;justify-items:start}.back{padding-inline-start:0;border:0;background:transparent;color:var(--accent)}.eyebrow{display:flex;align-items:center;gap:.45rem;font-size:.75rem;font-weight:700;color:var(--accent);line-height:1.5}.subtitle{font-size:.85rem;color:var(--muted)}.outcome-card{display:flex;align-items:start;gap:1rem;background:var(--panel);border:1px solid var(--line);border-inline-start:4px solid var(--accent);border-radius:.75rem;padding:1.25rem;min-width:0}.outcome-card>div{flex:1;min-width:0}.outcome-card h2{overflow-wrap:anywhere;margin:.25rem 0 .45rem;font-size:1.25rem}.outcome-card p{font-size:.9rem;color:var(--muted);overflow-wrap:anywhere}.outcome-icon{display:grid;place-items:center;padding:.6rem;border-radius:.6rem;background:var(--accent-soft);color:var(--accent);flex-shrink:0}.outcome-card.ok{border-inline-start-color:var(--status-ok)}.outcome-card.attention{border-inline-start-color:var(--status-escalated)}.outcome-card.fail{border-inline-start-color:var(--status-fail)}.ok .outcome-icon{color:var(--status-ok)}.attention .outcome-icon{color:var(--status-escalated)}.fail .outcome-icon{color:var(--status-fail)}.outcome-card .reason{margin-top:.75rem;color:var(--text)}.reason strong{display:block;font-size:.8rem;margin-bottom:.2rem}.primary-link{flex-shrink:0;border:1px solid var(--accent);border-radius:.5rem;padding:.65rem .85rem;font-size:.85rem;font-weight:650}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.25rem;padding:.25rem 0}.facts>div,.seat-facts>div{display:grid;gap:.4rem;min-width:0}dt{color:var(--muted);font-size:.8rem}dd{font-weight:600;font-size:.95rem;overflow-wrap:anywhere}.facts dd{text-transform:capitalize}.delivery-note{font-size:.85rem;color:var(--muted)}.card{background:var(--panel);border:1px solid var(--line);border-radius:.75rem;min-width:0;padding:1.25rem}.section-header{display:flex;flex-wrap:wrap;align-items:start;justify-content:space-between;gap:1rem;margin-bottom:1.25rem}.section-header>div{flex:1 1 20rem;display:grid;gap:.35rem;min-width:0}.section-header p:not(.eyebrow){color:var(--muted);font-size:.85rem}.section-header>button{flex-shrink:0;max-width:100%;white-space:nowrap}.count{font-size:.8rem;color:var(--muted);font-variant-numeric:tabular-nums}.sequence{border-top:3px solid var(--accent)}.stages{list-style:none;margin:0;padding:0}.stages>li{display:grid;grid-template-columns:2.25rem minmax(0,1fr);gap:.85rem;padding:1rem 0;border-top:1px solid var(--line)}.step-number{display:grid;place-items:center;align-self:start;width:2.1rem;height:2.1rem;border:1px solid var(--line);border-radius:.5rem;font:.8rem/1 var(--mono);color:var(--muted)}.stage-summary{margin-bottom:1.5rem;padding-bottom:1rem;border-bottom:1px solid var(--line)}.stage-summary-header{display:flex;align-items:baseline;gap:1rem;justify-content:space-between;margin-bottom:.75rem}.stage-summary-header h3{font-size:.85rem}.stage-strip{list-style:none;display:flex;flex-wrap:wrap;gap:.5rem .75rem;padding:0;margin:0}.stage-strip li{display:flex;align-items:center;gap:.35rem;padding:.35rem .5rem;border:1px solid var(--line);border-radius:.35rem;font-size:.75rem;color:var(--muted)}.stage-strip li span{color:var(--text)}.stage-strip li :global(svg){flex-shrink:0}.stage-strip .ok{color:var(--status-ok)}.stage-strip .fail{color:var(--status-fail)}.stage-strip .attention{color:var(--status-escalated)}.stage-details{margin-top:.65rem}.stage-details>summary{color:var(--accent);font-size:.8rem;padding:.5rem 0;min-height:2.5rem}.stage-evidence{display:grid;gap:1rem;padding:.5rem 0 1rem;min-width:0}.stage-heading{display:flex;gap:.6rem 1rem;flex-wrap:wrap;justify-content:space-between;align-items:center}.status-badge{font-size:.75rem;padding:.25rem .5rem;border:1px solid var(--line);border-radius:.4rem;overflow-wrap:anywhere}.status-badge.ok,.check-result.ok{color:var(--status-ok)}.status-badge.fail,.check-result.fail{color:var(--status-fail)}.status-badge.attention,.check-result.attention{color:var(--status-escalated)}.status-badge.quiet,.check-result.quiet{color:var(--muted)}.checks{list-style:none;margin:.65rem 0 0;padding:0;display:grid;gap:.5rem}.checks li{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.2rem 1rem;font-size:.85rem}.checks li>span:first-child{text-transform:capitalize}.checks p{width:100%;color:var(--muted);overflow-wrap:anywhere}.check-result{font-weight:600}.seat-picker{display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:1rem}.seat-picker button{text-transform:capitalize}.seat-picker [aria-pressed=true]{border-color:var(--accent);background:var(--accent-soft);color:var(--accent);box-shadow:inset 0 -2px var(--accent);font-weight:650}.seat-facts{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr) minmax(0,1fr);gap:1rem;padding:1rem;background:var(--panel-raised);border-radius:.5rem;margin-bottom:1rem}.seat-facts dd{font-size:.85rem}.read-error,.data-warning{padding:.85rem;border-inline-start:3px solid var(--status-escalated);background:var(--panel-raised);font-size:.85rem;overflow-wrap:anywhere}.read-error p{margin-top:.25rem}.read-error,.read-status{margin-bottom:.85rem}.read-status,.empty{color:var(--muted);font-size:.85rem}.recording,.journal-disclosure{border-top:1px solid var(--line);min-width:0}summary{display:flex;align-items:center;gap:.65rem;padding:.85rem 0;min-height:3rem;list-style:none;cursor:pointer;font-size:.85rem;font-weight:600}summary::-webkit-details-marker{display:none}summary>span:first-of-type{flex:1;overflow-wrap:anywhere;min-width:0}summary :global(svg){flex-shrink:0;color:var(--accent)}.disclosure-hint{color:var(--accent);font-size:.75rem;font-weight:400}details[open]>summary :global(.chevron){transform:rotate(180deg)}.check-evidence{width:100%;min-width:0}.check-evidence summary{justify-content:start;font-size:.8rem;font-weight:400;color:var(--accent);min-height:2.25rem;padding:.35rem 0}.recording pre,.check-evidence pre{white-space:pre-wrap;max-width:100%;overflow-wrap:anywhere;margin:0 0 1rem;padding:1rem;background:var(--panel-raised);border-radius:.5rem;font:.8rem/1.6 var(--mono)}.journal-lines{list-style:none;margin:0;padding:0}.journal-lines li{display:flex;gap:1rem;padding:.75rem 0;border-top:1px solid var(--line);font-size:.85rem}.event-number{font:.75rem/1.6 var(--mono);color:var(--muted);width:1.5rem;flex-shrink:0}.journal-lines li>div{min-width:0;overflow-wrap:anywhere}.event-stage{margin-inline-start:.65rem;color:var(--muted)}.journal-lines p{color:var(--muted);margin-top:.2rem}.coverage{background:var(--panel);border:1px solid var(--line);border-radius:.6rem;padding:.25rem 1.25rem}.coverage p,.coverage dd{font-size:.85rem;font-weight:400;color:var(--muted)}.coverage p{margin:.25rem 0 1rem}.coverage dl>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,3fr);gap:1rem;border-top:1px solid var(--line);padding:.6rem 0}.coverage dt{text-transform:capitalize}.coverage dd{overflow-wrap:anywhere}@media(hover:hover){button:not(:disabled):hover,summary:hover{background:var(--panel-raised)}}@media(max-width:700px){.lean-detail{padding:1.5rem 1rem 3rem}.outcome-card{flex-wrap:wrap}.outcome-card>div{flex-basis:calc(100% - 4rem)}.primary-link{margin-inline-start:0;max-width:100%;flex-shrink:1}.facts,.seat-facts{grid-template-columns:1fr;gap:1rem}.section-header{flex-wrap:wrap}.card{padding:1rem}.coverage{padding:.25rem 1rem}.coverage dl>div{grid-template-columns:1fr;gap:.3rem}.stages>li{grid-template-columns:1.8rem minmax(0,1fr);gap:.65rem}.step-number{width:1.7rem;height:1.7rem}.disclosure-hint{display:none}}
:global([dir=rtl]) .back :global(svg){transform:scaleX(-1)}
</style>
